create table public.emr_treatment_library(id text primary key check(id='clinic'),revision integer not null default 0,updated_at timestamptz not null default now());
create table public.emr_treatment_library_versions(revision integer primary key, nodes jsonb not null check(jsonb_typeof(nodes)='array' and octet_length(nodes::text)<=2000000),actor_id uuid references auth.users(id),created_at timestamptz not null default now());
create index emr_treatment_library_actor_idx on public.emr_treatment_library_versions(actor_id);
create table public.emr_treatment_plans(id uuid primary key default gen_random_uuid(),patient_id uuid not null references public.clinical_patients(id),owner_id uuid not null default auth.uid() references auth.users(id),revision integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index emr_treatment_plans_patient_idx on public.emr_treatment_plans(patient_id,owner_id,updated_at desc);
create index emr_treatment_plans_owner_idx on public.emr_treatment_plans(owner_id);
create table public.emr_treatment_plan_versions(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.emr_treatment_plans(id),revision integer not null,snapshot jsonb not null check(jsonb_typeof(snapshot)='object' and octet_length(snapshot::text)<=2000000),library_revision integer not null references public.emr_treatment_library_versions(revision),actor_id uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),unique(plan_id,revision));
create index emr_treatment_plan_library_idx on public.emr_treatment_plan_versions(library_revision);
create index emr_treatment_plan_actor_idx on public.emr_treatment_plan_versions(actor_id);
alter table public.emr_treatment_library enable row level security;
alter table public.emr_treatment_library_versions enable row level security;
alter table public.emr_treatment_plans enable row level security;
alter table public.emr_treatment_plan_versions enable row level security;
revoke all on public.emr_treatment_library,public.emr_treatment_library_versions,public.emr_treatment_plans,public.emr_treatment_plan_versions from public,anon,authenticated;
grant select on public.emr_treatment_library to authenticated;
grant update(revision,updated_at) on public.emr_treatment_library to authenticated;
grant select,insert on public.emr_treatment_library_versions to authenticated;
grant select,insert on public.emr_treatment_plans to authenticated;
grant update(revision,updated_at) on public.emr_treatment_plans to authenticated;
grant select,insert on public.emr_treatment_plan_versions to authenticated;
create policy planner_library_read on public.emr_treatment_library for select to authenticated using ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy planner_library_update on public.emr_treatment_library for update to authenticated using ((select private.current_user_is_admin()) and (select private.patient_secure_session())) with check ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy planner_library_versions_read on public.emr_treatment_library_versions for select to authenticated using ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy planner_library_versions_add on public.emr_treatment_library_versions for insert to authenticated with check (actor_id=(select auth.uid()) and (select private.current_user_is_admin()) and (select private.patient_secure_session()) and revision=(select l.revision from public.emr_treatment_library l where id='clinic'));
create policy planner_patient_read on public.emr_treatment_plans for select to authenticated using (owner_id=(select auth.uid()) and (select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy planner_patient_add on public.emr_treatment_plans for insert to authenticated with check (owner_id=(select auth.uid()) and revision=0 and (select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy planner_patient_update on public.emr_treatment_plans for update to authenticated using (owner_id=(select auth.uid()) and (select private.current_user_is_admin()) and (select private.patient_secure_session())) with check (owner_id=(select auth.uid()) and (select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy planner_versions_read on public.emr_treatment_plan_versions for select to authenticated using (actor_id=(select auth.uid()) and (select private.current_user_is_admin()) and (select private.patient_secure_session()) and exists(select 1 from public.emr_treatment_plans p where p.id=plan_id and p.owner_id=auth.uid()));
create policy planner_versions_add on public.emr_treatment_plan_versions for insert to authenticated with check (actor_id=(select auth.uid()) and (select private.current_user_is_admin()) and (select private.patient_secure_session()) and exists(select 1 from public.emr_treatment_plans p where p.id=plan_id and p.owner_id=auth.uid() and p.revision=emr_treatment_plan_versions.revision));

create function private.validate_planner_library(p_nodes jsonb) returns void language plpgsql security invoker set search_path='' as $$
declare n jsonb;parent_kind text;kinds text[]:=array['problem','definition','goal','objective','intervention'];level integer;
begin
 if jsonb_typeof(p_nodes) is distinct from 'array' or jsonb_array_length(p_nodes) not between 1 and 5000 or octet_length(p_nodes::text)>2000000 then raise exception 'Invalid library size';end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(p_nodes) x)<>jsonb_array_length(p_nodes) then raise exception 'Duplicate library IDs';end if;
 for n in select value from jsonb_array_elements(p_nodes) loop
  level:=array_position(kinds,n->>'kind');
  if level is null or jsonb_typeof(n->'id') is distinct from 'string' or length(n->>'id') not between 1 and 100 or jsonb_typeof(n->'text') is distinct from 'string' or length(btrim(n->>'text')) not between 1 and 2000 or jsonb_typeof(n->'active') is distinct from 'boolean' then raise exception 'Invalid library item';end if;
  if level=1 then if n->>'parent' is not null then raise exception 'Problem must be a root';end if;
  else select x->>'kind' into parent_kind from jsonb_array_elements(p_nodes) x where x->>'id'=n->>'parent';if parent_kind is distinct from kinds[level-1] then raise exception 'Invalid parent relationship';end if;end if;
 end loop;
end;$$;
create function public.save_emr_treatment_library(p_expected integer,p_nodes jsonb) returns integer language plpgsql security invoker set search_path='' as $$
declare current_revision integer;
begin
 perform private.validate_planner_library(p_nodes);
 select revision into current_revision from public.emr_treatment_library where id='clinic' for update;
 if not found then raise exception 'Library unavailable' using errcode='42501';end if;
 if current_revision is distinct from p_expected then raise exception 'Library changed in another session' using errcode='40001';end if;
 -- IDs and parent links are stable. Move content by adding a new item and deactivating the old one.
 if exists(select 1 from public.emr_treatment_library_versions v,jsonb_array_elements(v.nodes) prior_node where v.revision=current_revision and not exists(select 1 from jsonb_array_elements(p_nodes) new where new->>'id'=prior_node->>'id' and new->>'kind'=prior_node->>'kind' and new->'parent'=prior_node->'parent')) then raise exception 'Retain existing IDs and parent links; deactivate items instead of removing them';end if;
 update public.emr_treatment_library set revision=current_revision+1,updated_at=now() where id='clinic';
 insert into public.emr_treatment_library_versions(revision,nodes,actor_id) values(current_revision+1,p_nodes,auth.uid());return current_revision+1;
end;$$;

create function private.resolve_planner_node(p_selection jsonb,p_kind text,p_parent text,p_nodes jsonb,p_final boolean) returns jsonb language plpgsql security invoker set search_path='' as $$
declare source jsonb;child jsonb;resolved jsonb:='[]'::jsonb;children jsonb:=coalesce(p_selection->'children','[]');next_kind text;max_children integer:=20;wording text;
begin
 select x into source from jsonb_array_elements(p_nodes) x where x->>'id'=p_selection->>'id' and x->>'kind'=p_kind and x->>'parent' is not distinct from p_parent and x->>'active'='true';
 if source is null then raise exception 'Selection does not belong to its active library parent';end if;
 if jsonb_typeof(children) is distinct from 'array' then raise exception 'Invalid selected children';end if;
 if p_kind='problem' then max_children:=2;end if;
 if jsonb_array_length(children)>max_children then raise exception 'Too many selected items; problems allow at most two definitions';end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(children) x)<>jsonb_array_length(children) then raise exception 'Duplicate selected items';end if;
 next_kind:=case p_kind when 'problem' then 'definition' when 'definition' then 'goal' when 'goal' then 'objective' when 'objective' then 'intervention' else null end;
 if next_kind is null and jsonb_array_length(children)>0 then raise exception 'Interventions cannot have children';end if;
 if p_final and next_kind is not null and jsonb_array_length(children)=0 then raise exception 'A finalized plan requires every selected branch to reach an intervention';end if;
 if p_final and p_kind='goal' and p_selection->>'agreed' is distinct from 'true' then raise exception 'Record patient agreement on every finalized goal';end if;
 wording:=coalesce(nullif(btrim(p_selection->>'text'),''),source->>'text');if length(wording)>2000 then raise exception 'Patient wording is too long';end if;
 for child in select value from jsonb_array_elements(children) loop resolved:=resolved||jsonb_build_array(private.resolve_planner_node(child,next_kind,p_selection->>'id',p_nodes,p_final));end loop;
 return jsonb_build_object('id',source->>'id','kind',p_kind,'source_text',source->>'text','text',wording,'primary',coalesce(p_selection->>'primary','false')='true','agreed',coalesce(p_selection->>'agreed','false')='true','children',resolved);
end;$$;
create function public.save_emr_treatment_plan(p_id uuid,p_patient uuid,p_expected integer,p_library_revision integer,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare r public.emr_treatment_plans;lib integer;nodes jsonb;selected jsonb;problems jsonb:='[]';person jsonb;provider text;finalized boolean;review text;plan_id uuid;next_revision integer;snapshot jsonb;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>1000000 or coalesce(p_input->>'status','') not in ('draft','finalized') then raise exception 'Invalid plan';end if;
 finalized:=p_input->>'status'='finalized';
 if jsonb_typeof(p_input->'problems') is distinct from 'array' or jsonb_array_length(p_input->'problems') not between 1 and 5 then raise exception 'Choose between one and five problems';end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(p_input->'problems') x)<>jsonb_array_length(p_input->'problems') then raise exception 'Choose different problems';end if;
 if finalized and (select count(*) from jsonb_array_elements(p_input->'problems') x where x->>'primary'='true')<>1 then raise exception 'Choose exactly one primary problem';end if;
 if finalized and p_input->>'reviewed' is distinct from 'true' then raise exception 'Clinician review is required to finalize';end if;
 if length(btrim(coalesce(p_input->>'title',''))) not between 1 and 140 or length(coalesce(p_input->>'notes',''))>8000 then raise exception 'Enter a plan title and notes within the field limits';end if;
 review:=coalesce(p_input->>'review_date','');if review<>'' then if review!~'^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid review date';end if;perform review::date;end if;
 select revision into lib from public.emr_treatment_library where id='clinic' for share;
 if lib is null then raise exception 'Library unavailable' using errcode='42501';end if;
 if lib is distinct from p_library_revision then raise exception 'Library changed. Reload choices before saving.' using errcode='40001';end if;
 select v.nodes into nodes from public.emr_treatment_library_versions v where v.revision=lib;
 select demographics into person from public.clinical_patients where id=p_patient;if person is null then raise exception 'Patient unavailable' using errcode='42501';end if;
 select full_name into provider from public.profiles where id=auth.uid();
 for selected in select value from jsonb_array_elements(p_input->'problems') loop problems:=problems||jsonb_build_array(private.resolve_planner_node(selected,'problem',null,nodes,finalized));end loop;
 if p_id is null then
  if p_expected is distinct from 0 then raise exception 'Invalid initial revision';end if;
  insert into public.emr_treatment_plans(patient_id) values(p_patient) returning * into r;
 else select * into r from public.emr_treatment_plans where id=p_id and patient_id=p_patient for update;if not found then raise exception 'Plan unavailable' using errcode='42501';end if;end if;
 if r.revision is distinct from p_expected then raise exception 'Plan changed in another session' using errcode='40001';end if;
 next_revision:=r.revision+1;
 snapshot:=jsonb_build_object('title',btrim(p_input->>'title'),'notes',coalesce(p_input->>'notes',''),'review_date',review,'status',p_input->>'status','library_revision',lib,'patient_name',btrim(coalesce(person->>'first_name','')||' '||coalesce(person->>'last_name','')),'patient_dob',coalesce(person->>'dob',''),'clinician_name',coalesce(provider,'Clinic clinician'),'created_at',now(),'problems',problems);
 update public.emr_treatment_plans set revision=next_revision,updated_at=now() where id=r.id;
 insert into public.emr_treatment_plan_versions(plan_id,revision,snapshot,library_revision) values(r.id,next_revision,snapshot,lib);
 return jsonb_build_object('id',r.id,'revision',next_revision,'snapshot',snapshot);
end;$$;
revoke all on function private.validate_planner_library(jsonb),private.resolve_planner_node(jsonb,text,text,jsonb,boolean) from public,anon;
grant execute on function private.validate_planner_library(jsonb),private.resolve_planner_node(jsonb,text,text,jsonb,boolean) to authenticated;
revoke all on function public.save_emr_treatment_library(integer,jsonb),public.save_emr_treatment_plan(uuid,uuid,integer,integer,jsonb) from public,anon;
grant execute on function public.save_emr_treatment_library(integer,jsonb),public.save_emr_treatment_plan(uuid,uuid,integer,integer,jsonb) to authenticated;

create function private.guard_treatment_header() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.revision<>old.revision+1 then raise exception 'Advance exactly one revision';end if;
 new.updated_at:=now();return new;
end;$$;
create trigger treatment_library_header before update on public.emr_treatment_library for each row execute function private.guard_treatment_header();
create trigger treatment_plan_header before update on public.emr_treatment_plans for each row execute function private.guard_treatment_header();
create function private.guard_treatment_library_version() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 perform private.validate_planner_library(new.nodes);
 if new.revision>1 and exists(select 1 from public.emr_treatment_library_versions v,jsonb_array_elements(v.nodes) prior_node where v.revision=new.revision-1 and not exists(select 1 from jsonb_array_elements(new.nodes) n where n->>'id'=prior_node->>'id' and n->>'kind'=prior_node->>'kind' and n->'parent'=prior_node->'parent')) then raise exception 'Retain existing IDs and parent links';end if;
 return new;
end;$$;
create trigger treatment_library_version_guard before insert on public.emr_treatment_library_versions for each row execute function private.guard_treatment_library_version();
create function private.guard_treatment_plan_version() returns trigger language plpgsql security invoker set search_path='' as $$
declare node jsonb;resolved jsonb:='[]';nodes jsonb;person jsonb;provider text;finalized boolean;
begin
 if (new.snapshot->>'library_revision')::integer is distinct from new.library_revision or new.library_revision is distinct from (select revision from public.emr_treatment_library where id='clinic') then raise exception 'Library revision does not match';end if;
 if coalesce(new.snapshot->>'status','') not in ('draft','finalized') or jsonb_typeof(new.snapshot->'problems') is distinct from 'array' or jsonb_array_length(new.snapshot->'problems') not between 1 and 5 then raise exception 'Invalid plan snapshot';end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(new.snapshot->'problems') x)<>jsonb_array_length(new.snapshot->'problems') then raise exception 'Duplicate selected problems';end if;
 finalized:=new.snapshot->>'status'='finalized';
 if finalized and (select count(*) from jsonb_array_elements(new.snapshot->'problems') x where x->>'primary'='true')<>1 then raise exception 'Choose exactly one primary problem';end if;
 select v.nodes into nodes from public.emr_treatment_library_versions v where v.revision=new.library_revision;
 for node in select value from jsonb_array_elements(new.snapshot->'problems') loop resolved:=resolved||jsonb_build_array(private.resolve_planner_node(node,'problem',null,nodes,finalized));end loop;
 if resolved is distinct from new.snapshot->'problems' then raise exception 'Snapshot source wording or hierarchy does not match its library';end if;
 select p.demographics into person from public.clinical_patients p join public.emr_treatment_plans r on r.patient_id=p.id where r.id=new.plan_id and r.owner_id=auth.uid();
 select full_name into provider from public.profiles where id=auth.uid();
 if person is null or new.snapshot->>'patient_name' is distinct from btrim(coalesce(person->>'first_name','')||' '||coalesce(person->>'last_name','')) or new.snapshot->>'patient_dob' is distinct from coalesce(person->>'dob','') or new.snapshot->>'clinician_name' is distinct from coalesce(provider,'Clinic clinician') then raise exception 'Snapshot patient or clinician binding does not match';end if;
 if length(btrim(coalesce(new.snapshot->>'title',''))) not between 1 and 140 or length(coalesce(new.snapshot->>'notes',''))>8000 then raise exception 'Invalid plan snapshot wording';end if;
 return new;
end;$$;
create trigger treatment_plan_version_guard before insert on public.emr_treatment_plan_versions for each row execute function private.guard_treatment_plan_version();
revoke all on function private.guard_treatment_header(),private.guard_treatment_library_version(),private.guard_treatment_plan_version() from public,anon,authenticated;

